class Solution {
public:
    int maximumTastiness(vector<int>& price, int k) {
        sort(price.begin(), price.end());
        int lo = 0;
        int hi = price.back() - price.front();
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (canPick(price, k, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }
private:
    bool canPick(vector<int>& price, int k, int x) {
        int count = 1;
        int last = price[0];
        for (int i = 1; i < (int)price.size(); i++) {
            if (price[i] - last >= x) {
                count++;
                last = price[i];
                if (count >= k) return true;
            }
        }
        return count >= k;
    }
};
